function ScoreForm({
	players,
	onSelectPlayer,
	player1Score,
	player2Score,
	onAddP1Score,
	onAddP2Score,
}) {
	const playerObj = players.map((player) => player);

	const {
		id,
		playerName,
		points,
		wins,
		draws,
		losses,
		goalsFor,
		goalsAgainst,
		goalDifference,
	} = playerObj;

	function handleSubmit(e) {
		e.preventDefault();
	}
	return (
		<form onSubmit={handleSubmit}>
			<span>
				<select
					value={playerName}
					onChange={(e) => onSelectPlayer(e.target.value)}
				>
					<option value="Home" disabled>
						Home Team
					</option>
					<option value={playerObj[0].playerName}>
						{playerObj[0].playerName}
					</option>
					<option value={playerObj[1].playerName}>
						{playerObj[1].playerName}
					</option>
					<option value={playerObj[2].playerName}>
						{playerObj[2].playerName}
					</option>
				</select>
				<input
					type="number"
					value={player1Score}
					onChange={(e) => onAddP1Score(e.target.value)}
				/>
			</span>
			:
			<span>
				<select
					required
					value={playerName}
					onChange={(e) => onSelectPlayer(e.target.value)}
				>
					<option value="" disabled>
						Away Team
					</option>
					<option value={playerObj[0].playerName}>
						{playerObj[0].playerName}
					</option>
					<option value={playerObj[1].playerName}>
						{playerObj[1].playerName}
					</option>
					<option value={playerObj[2].playerName}>
						{playerObj[2].playerName}
					</option>
				</select>
				<input
					type="number"
					value={player2Score}
					onChange={(e) => onAddP2Score(e.target.value)}
				/>
			</span>
			<button onClick={() => console.log(player1Score, player2Score)}>
				Add
			</button>
		</form>
	);
}
export default ScoreForm;
